package cache

import (
	"bytes"
	"container/list"
	"crypto/aes"
	"crypto/cipher"
	"crypto/rand"
	"encoding/binary"
	"errors"
	"runtime"
	"sync"
	"sync/atomic"
	"time"
)

// KeyVersion represents a cryptographic key version identifier.
type KeyVersion string

// KeyMaterial holds AES-256 key bytes securely.
type KeyMaterial struct {
	keyBytes []byte // 32 bytes for AES-256
}

// Zero zeroes out the key material securely, resistant to compiler optimizations.
func (k *KeyMaterial) Zero() {
	if k.keyBytes == nil {
		return
	}
	for i := range k.keyBytes {
		k.keyBytes[i] = 0
	}
	// Prevent compiler optimizations from eliding zeroing.
	runtime.KeepAlive(k.keyBytes)
}

// Encryptor manages encryption/decryption keys and nonce counters.
type Encryptor struct {
	mu         sync.RWMutex
	keys       map[KeyVersion]*KeyMaterial // key version -> key material
	nonceCtrs  map[KeyVersion]*uint32      // atomic counters per key version
	keyOrder   []KeyVersion                 // ordered key versions, newest first
	maxKeys    int                          // max cached keys to avoid unbounded growth
}

// NewEncryptor creates an Encryptor with empty key cache.
func NewEncryptor(maxKeys int) *Encryptor {
	return &Encryptor{
		keys:      make(map[KeyVersion]*KeyMaterial),
		nonceCtrs: make(map[KeyVersion]*uint32),
		maxKeys:   maxKeys,
	}
}

// AddKey adds or rotates in a new key version, evicting oldest if needed.
// If keyVersion exists, replaces key material and resets nonce counter.
func (e *Encryptor) AddKey(version KeyVersion, keyBytes []byte) error {
	if len(keyBytes) != 32 {
		return errors.New("key length must be 32 bytes for AES-256")
	}
	e.mu.Lock()
	defer e.mu.Unlock()

	// Zero old key if replacing
	if oldKey, ok := e.keys[version]; ok {
		oldKey.Zero()
	}

	// Store new key material securely
	keyCopy := make([]byte, 32)
	copy(keyCopy, keyBytes)
	e.keys[version] = &KeyMaterial{keyBytes: keyCopy}

	// Initialize or reset nonce counter
	var zero uint32 = 0
	e.nonceCtrs[version] = &zero

	// Insert version at front of order slice, removing duplicates
	var newOrder []KeyVersion
	newOrder = append(newOrder, version)
	for _, v := range e.keyOrder {
		if v != version {
			newOrder = append(newOrder, v)
		}
	}
	e.keyOrder = newOrder

	// Evict oldest keys if exceeding cache size
	if len(e.keyOrder) > e.maxKeys {
		evict := e.keyOrder[len(e.keyOrder)-1]
		e.keyOrder = e.keyOrder[:len(e.keyOrder)-1]
		if oldKey, ok := e.keys[evict]; ok {
			oldKey.Zero()
			delete(e.keys, evict)
		}
		delete(e.nonceCtrs, evict)
	}

	return nil
}

// RemoveKey securely removes a key version.
func (e *Encryptor) RemoveKey(version KeyVersion) {
	e.mu.Lock()
	defer e.mu.Unlock()
	if key, ok := e.keys[version]; ok {
		key.Zero()
		delete(e.keys, version)
	}
	delete(e.nonceCtrs, version)
	for i, v := range e.keyOrder {
		if v == version {
			e.keyOrder = append(e.keyOrder[:i], e.keyOrder[i+1:]...)
			break
		}
	}
}

// generateNonce creates a 12-byte AES-GCM nonce:
// 8 bytes random + 4 bytes atomic counter (big endian).
func (e *Encryptor) generateNonce(version KeyVersion) ([]byte, error) {
	nonce := make([]byte, 12)
	// 8 random bytes prefix
	if _, err := rand.Read(nonce[:8]); err != nil {
		return nil, err
	}

	e.mu.RLock()
	counterPtr, ok := e.nonceCtrs[version]
	e.mu.RUnlock()
	if !ok {
		return nil, errors.New("nonce counter not found for key version")
	}

	// Atomically increment counter
	ctr := atomic.AddUint32(counterPtr, 1)

	// Append counter as last 4 bytes big endian
	binary.BigEndian.PutUint32(nonce[8:], ctr)
	return nonce, nil
}

// Encrypt encrypts plaintext with the given key version and returns:
// nonce || ciphertext || tag (AES-GCM standard output).
func (e *Encryptor) Encrypt(version KeyVersion, plaintext []byte) ([]byte, error) {
	e.mu.RLock()
	keyMat, ok := e.keys[version]
	e.mu.RUnlock()
	if !ok {
		return nil, errors.New("encryption key version not found")
	}

	block, err := aes.NewCipher(keyMat.keyBytes)
	if err != nil {
		return nil, err
	}
	aesgcm, err := cipher.NewGCM(block)
	if err != nil {
		return nil, err
	}

	nonce, err := e.generateNonce(version)
	if err != nil {
		return nil, err
	}

	ciphertext := aesgcm.Seal(nil, nonce, plaintext, nil)

	// Prepare output: prepend nonce to ciphertext (nonce is needed for decryption)
	out := make([]byte, 0, len(nonce)+len(ciphertext))
	out = append(out, nonce...)
	out = append(out, ciphertext...)

	// Securely zero plaintext buffer immediately after use
	zeroize(plaintext)

	return out, nil
}

// Decrypt attempts to decrypt ciphertext using latest key versions in fallback order.
// It expects input as nonce || ciphertext|| tag.
// Returns plaintext on success or error on failure.
func (e *Encryptor) Decrypt(data []byte) ([]byte, KeyVersion, error) {
	if len(data) < 12 {
		return nil, "", errors.New("ciphertext too short")
	}

	nonce := data[:12]
	ciphertext := data[12:]

	e.mu.RLock()
	versions := make([]KeyVersion, len(e.keyOrder))
	copy(versions, e.keyOrder)
	e.mu.RUnlock()

	var lastErr error
	for _, version := range versions {
		e.mu.RLock()
		keyMat, ok := e.keys[version]
		e.mu.RUnlock()
		if !ok {
			continue
		}

		block, err := aes.NewCipher(keyMat.keyBytes)
		if err != nil {
			lastErr = err
			continue
		}

		aesgcm, err := cipher.NewGCM(block)
		if err != nil {
			lastErr = err
			continue
		}

		plaintext, err := aesgcm.Open(nil, nonce, ciphertext, nil)
		if err == nil {
			// Successful decryption - zero ciphertext buffer immediately if possible
			zeroize(ciphertext)
			return plaintext, version, nil
		}

		lastErr = err
	}

	// Failed all versions
	return nil, "", lastErr
}

// zeroize securely zeroes a byte slice in a way resistant to compiler optimizations.
func zeroize(b []byte) {
	if b == nil {
		return
	}
	for i := range b {
		b[i] = 0
	}
	// Prevent compiler optimization removing zeroing
	runtime.KeepAlive(b)
}

