```go
package cache

import (
	"bytes"
	"container/list"
	"crypto/aes"
	"crypto/cipher"
	"crypto/rand"
	"encoding/binary"
	"errors"
	"runtime"
	"sync"
	"sync/atomic"
)

// KeyVersion identifies a particular encryption key version.
type KeyVersion string

var (
	ErrCacheMiss        = errors.New("cache: key not found")
	ErrDecryptionFailed = errors.New("cache: decryption failed")
	ErrKeyNotFound      = errors.New("cache: encryption key not found")
	ErrInvalidCapacity  = errors.New("cache: capacity must be > 0")
)

// Encryptor manages AES-256 GCM encryption/decryption with nonce management and multi-version key fallback.
type Encryptor struct {
	mu          sync.RWMutex
	keys        map[KeyVersion]*aesGCMKey
	noncePrefix map[KeyVersion][]byte // 8 random bytes prefix per key version
	nonceCtr    map[KeyVersion]*uint32
}

type aesGCMKey struct {
	key  []byte
	aead cipher.AEAD
}

// NewEncryptor creates a new Encryptor instance.
func NewEncryptor() *Encryptor {
	return &Encryptor{
		keys:        make(map[KeyVersion]*aesGCMKey),
		noncePrefix: make(map[KeyVersion][]byte),
		nonceCtr:    make(map[KeyVersion]*uint32),
	}
}

// AddKey adds a new AES-256 key for the given key version.
// The key must be 32 bytes.
// Returns error if key length invalid or key version already exists.
func (e *Encryptor) AddKey(ver KeyVersion, key []byte) error {
	if len(key) != 32 {
		return errors.New("encryptor: key length must be 32 bytes")
	}
	e.mu.Lock()
	defer e.mu.Unlock()

	if _, exists := e.keys[ver]; exists {
		return errors.New("encryptor: key version already exists")
	}

	block, err := aes.NewCipher(key)
	if err != nil {
		return err
	}
	aead, err := cipher.NewGCM(block)
	if err != nil {
		return err
	}

	// Generate 8 random bytes nonce prefix.
	prefix := make([]byte, 8)
	if _, err := rand.Read(prefix); err != nil {
		return err
	}

	ctr := uint32(0)

	// Copy key slice to avoid external mutation.
	keyCopy := make([]byte, 32)
	copy(keyCopy, key)

	e.keys[ver] = &aesGCMKey{
		key:  keyCopy,
		aead: aead,
	}
	e.noncePrefix[ver] = prefix
	e.nonceCtr[ver] = &ctr

	return nil
}

// RemoveKey securely removes and zeroes key material for a key version.
func (e *Encryptor) RemoveKey(ver KeyVersion) {
	e.mu.Lock()
	defer e.mu.Unlock()
	if k, exists := e.keys[ver]; exists {
		zeroize(k.key)
		delete(e.keys, ver)
	}
	delete(e.noncePrefix, ver)
	delete(e.nonceCtr, ver)
}

// Encrypt encrypts plaintext under the specified key version, returning nonce||ciphertext||tag.
// It zeroes plaintext buffer securely after use.
// Returns error if key version not found or encryption fails.
func (e *Encryptor) Encrypt(ver KeyVersion, plaintext []byte) ([]byte, error) {
	e.mu.RLock()
	k, ok := e.keys[ver]
	prefix, prefixOk := e.noncePrefix[ver]
	ctrPtr, ctrOk := e.nonceCtr[ver]
	e.mu.RUnlock()

	if !ok || !prefixOk || !ctrOk {
		return nil, ErrKeyNotFound
	}

	// Construct nonce: 8 random prefix bytes + 4-byte atomic counter suffix.
	ctr := atomic.AddUint32(ctrPtr, 1) - 1 // zero-based
	nonce := make([]byte, 12)
	copy(nonce[:8], prefix)
	binary.BigEndian.PutUint32(nonce[8:], ctr)

	// Encrypt with AES-GCM (nonce length must be 12).
	ciphertext := k.aead.Seal(nil, nonce, plaintext, nil)

	// Securely zero plaintext buffer after encryption.
	zeroize(plaintext)

	// Output nonce || ciphertext (includes tag).
	out := make([]byte, 12+len(ciphertext))
	copy(out[:12], nonce)
	copy(out[12:], ciphertext)

	// Prevent zeroing from being optimized away.
	runtime.KeepAlive(plaintext)
	return out, nil
}

// Decrypt attempts to decrypt ciphertext (nonce||ciphertext||tag) using the specified key version.
// If decryption fails, attempts fallback keys in order provided by fallbackVersions.
// Zeroes ciphertext buffer securely after use.
// Returns plaintext or error.
func (e *Encryptor) Decrypt(ver KeyVersion, ciphertext []byte, fallbackVersions []KeyVersion) ([]byte, error) {
	// Validate input length.
	if len(ciphertext) < 12 {
		return nil, ErrDecryptionFailed
	}
	nonce := ciphertext[:12]
	ct := ciphertext[12:]

	tryKeys := make([]KeyVersion, 0, len(fallbackVersions)+1)
	tryKeys = append(tryKeys, ver)
	tryKeys = append(tryKeys, fallbackVersions...)

	var lastErr error

	for _, keyVer := range tryKeys {
		e.mu.RLock()
		k, ok := e.keys[keyVer]
		e.mu.RUnlock()
		if !ok {
			lastErr = ErrKeyNotFound
			continue
		}

		plaintext, err := k.aead.Open(nil, nonce, ct, nil)
		if err == nil {
			// Securely zero ciphertext slice after decryption.
			zeroize(ciphertext)
			runtime.KeepAlive(ciphertext)
			return plaintext, nil
		}
		lastErr = err
	}

	// Securely zero ciphertext even if all attempts failed.
	zeroize(ciphertext)
	runtime.KeepAlive(ciphertext)

	if lastErr != nil {
		return nil, ErrDecryptionFailed
	}
	return nil, ErrDecryptionFailed
}

// zeroize securely zeros the byte slice.
func zeroize(b []byte) {
	for i := range b {
		b[i] = 0
	}
	// Prevent compiler optimization.
	runtime.KeepAlive(b)
}

