// Encrypt encrypts plaintext under the specified key version, returning nonce||ciphertext||tag.
// It zeroes plaintext buffer securely after use.
// Returns error if key version not found or encryption fails.
func (e *Encryptor) Encrypt(ver KeyVersion, plaintext []byte) ([]byte, error) {
	e.mu.RLock()
	k, ok := e.keys[ver]
	prefix, prefixOk := e.noncePrefix[ver]
	ctrPtr, ctrOk := e.nonceCtr[ver]
	e.mu.RUnlock()

	if !ok || !prefixOk || !ctrOk {
		return nil, ErrKeyNotFound
	}

	// Construct nonce: 8 random prefix bytes + 4-byte atomic counter suffix.
	ctr := atomic.AddUint32(ctrPtr, 1) - 1 // zero-based
	nonce := make([]byte, 12)
	copy(nonce[:8], prefix)
	binary.BigEndian.PutUint32(nonce[8:], ctr)

	// Encrypt with AES-GCM (nonce length must be 12).
	ciphertext := k.aead.Seal(nil, nonce, plaintext, nil)

	// Securely zero plaintext buffer after encryption.
	zeroize(plaintext)

	// Output nonce || ciphertext (includes tag).
	out := make([]byte, 12+len(ciphertext))
	copy(out[:12], nonce)
	copy(out[12:], ciphertext)

	// Prevent zeroing from being optimized away.
	runtime.KeepAlive(plaintext)
	return out, nil
}

// Decrypt attempts to decrypt ciphertext (nonce||ciphertext||tag) using the specified key version.
// If decryption fails, attempts fallback keys in order provided by fallbackVersions.
// Zeroes ciphertext buffer securely after use.
// Returns plaintext or error.
func (e *Encryptor) Decrypt(ver KeyVersion, ciphertext []byte, fallbackVersions []KeyVersion) ([]byte, error) {
	// Validate input length.
	if len(ciphertext) < 12 {
		return nil, ErrDecryptionFailed
	}
	nonce := ciphertext[:12]
	ct := ciphertext[12:]

	tryKeys := make([]KeyVersion, 0, len(fallbackVersions)+1)
	tryKeys = append(tryKeys, ver)
	tryKeys = append(tryKeys, fallbackVersions...)

	var lastErr error

	for _, keyVer := range tryKeys {
		e.mu.RLock()
		k, ok := e.keys[keyVer]
		e.mu.RUnlock()
		if !ok {
			lastErr = ErrKeyNotFound
			continue
		}

		plaintext, err := k.aead.Open(nil, nonce, ct, nil)
		if err == nil {
			// Securely zero ciphertext slice after decryption.
			zeroize(ciphertext)
			runtime.KeepAlive(ciphertext)
			return plaintext, nil
		}
		lastErr = err
