func (c *Cache) Put(key string, value []byte) error {
    c.mu.Lock()
    defer c.mu.Unlock()

    // Encrypt the plaintext value.
    ciphertext, err := c.encryptor.Encrypt(c.primaryKeyVersion, value)
    if err != nil {
        cacheEncryptionFailureTotal.Inc()
        return fmt.Errorf("encryption failed: %w", err)
    }
    cacheEncryptionSuccessTotal.Inc()

    // Check if entry exists.
    if ent, ok := c.cache[key]; ok {
        // Zero old ciphertext before replacement.
        zeroize(ent.value)
        ent.value = ciphertext

        // Move to front as most recently used.
        c.lruList.MoveToFront(ent.element)
    } else {
        // Insert new entry.
        ele := c.lruList.PushFront(key)
        c.cache[key] = &cacheEntry{
            key:     key,
            value:   ciphertext,
            element: ele,
        }

        // Evict if capacity exceeded.
        if c.lruList.Len() > c.capacity {
            back := c.lruList.Back()
            if back != nil {
                evictKey := back.Value.(string)
                evictEntry := c.cache[evictKey]

                // Zero ciphertext of evicted entry.
                zeroize(evictEntry.value)

                // Remove from map and list.
                delete(c.cache, evictKey)
                c.lruList.Remove(back)

                cacheEvictionTotal.Inc()
            }
        }
    }

    return nil
}
