                // Zero ciphertext of evicted entry.
                zeroize(evictEntry.value)

                // Remove from map and list.
                delete(c.cache, evictKey)
                c.lruList.Remove(back)

                cacheEvictionTotal.Inc()
            }
        }
    }

    return nil
}
```

