## 2. Implement `Get` method

```go
func (c *Cache) Get(key string) ([]byte, error) {
    c.mu.Lock()
    ent, ok := c.cache[key]
    if !ok {
        c.mu.Unlock()
        cacheMissTotal.Inc()
        return nil, ErrCacheMiss
    }
    // Move accessed entry to front (MRU).
    c.lruList.MoveToFront(ent.element)
    ciphertext := ent.value
    c.mu.Unlock()

    cacheHitTotal.Inc()

    // Attempt decrypt with primary key version plus fallback keys.
    plaintext, err := c.encryptor.Decrypt(c.primaryKeyVersion, ciphertext, c.fallbackKeyVersions)
    if err != nil {
        cacheDecryptionFailureTotal.Inc()
        return nil, fmt.Errorf("decryption failed: %w", err)
    }
    cacheDecryptionSuccessTotal.Inc()

    // Optionally zero ciphertext after decrypt (configurable).
    zeroize(ciphertext)

    return plaintext, nil
}
```

